from __future__ import annotations

from typing import Any

import jsonschema
import pytest

from llm_router._internal.capabilities.schema import SchemaSpec, with_schema_transform

pytestmark = pytest.mark.verification_kind("unit")


def parse_payload(value: object) -> object:
    assert isinstance(value, dict)
    return value


def identity(json_schema: Any) -> Any:
    return json_schema


def make_spec() -> SchemaSpec:
    json_schema = {
        "type": "object",
        "$defs": {
            "level": {"type": "string", "enum": ["low", "high"]},
        },
        "properties": {"level": {"$ref": "#/$defs/level"}},
        "required": ["level"],
        "minProperties": 1,
        "allOf": [{"required": ["level"]}],
    }
    return SchemaSpec(
        name="level_spec",
        json_schema=json_schema,
        parser=parse_payload,
    )


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_with_schema_transform_keeps_defs_enum_and_composition() -> None:
    spec = make_spec()

    result = with_schema_transform(spec, identity)

    for key in ("$defs", "minProperties", "allOf"):
        assert key in result.json_schema
    assert dict(result.json_schema) == dict(spec.json_schema)
    assert result.name == "level_spec"

    validator = jsonschema.Draft202012Validator(dict(result.json_schema))
    assert validator.is_valid({"level": "low"})
    assert not validator.is_valid({"level": "medium"})
    assert not validator.is_valid({})
    assert result.parse({"level": "high"}) == {"level": "high"}
